item.aggregated_output:
        record = MarcBinary(data)
        edition = read_edition(record)
        edition_builder = import_edition_builder.import_edition_builder(
            init_dict=edition
        )
        format = 'marc'
    else:
        raise DataError('unrecognised-import-format')

    parse_meta_headers(edition_builder)
    return edition_builder.get_dict(), format


class importapi:
    """/api/import endpoint for general data formats."""

    def error(self, error_code, error='Invalid item', **kwargs):
        content = {'success': False, 'error_code': error_code, 'error': error}
        content.update(kwargs)
        raise web.HTTPError('400 Bad Request', data=json.dumps(content))

    def POST(self):
        web.header('Content-Type', 'application/json')
        if not can_write():
            raise web.HTTPError('403 Forbidden')

        override_validation = (
            web.input().get('override-validation', '').lower() == 'true'
        )
        data = web.data()

        try:
            edition, format = parse_data(data)
            # Validation requires valid publishers and authors.
            # If data unavailable, provide throw-away data which validates
            # We use ["????"] as an override pattern
            if edition.get('publishers') == ["????"]:
                edition.pop('publishers')
            if edition.get('authors') == [{"name": "????"}]:
                edition.pop('authors')
            if edition.get('publish_date') == "????":
                edition.pop('publish_date')

        except DataError as e:
            return self.error(str(e), 'Failed to parse import data')
        except ValidationError as e:
            return self.error('invalid-value', str(e).replace('\n', ': '))

        if not edition:
            return self.error('unknown-error', 'Failed to parse import data')

        try:
            reply = add_book.load(edition, override_validation=override_validation)
            # TODO: If any records have been created, return a 201, otherwise 200
            return json.dumps(reply)
        except add_book.RequiredField as e:
            return self.error('missing-required-field', str(e))
        except ClientException as e:
            return self.error('bad-request', **json.loads(e.json))
        except TypeError as e:
            return self.error('type-error', repr(e))
        except Exception as e:
            return self.error('unhandled-exception', repr(e))


def raise_non_book_marc(marc_record, **kwargs):
    details = 'Item rejected'
    # Is the item a serial instead of a monograph?
    marc_leaders = marc_record.leader()
    if marc_leaders[7] == 's':
        raise BookImportError('item-is-serial', details, **kwargs)

    # insider note: follows Archive.org's approach of
    # Item::isMARCXMLforMonograph() which excludes non-books
    if not (marc_leaders[7] == 'm' and marc_leaders[6] == 'a'):
        raise BookImportError('item-not-book', details, **kwargs)


class ia_importapi(importapi):
    """/api/import/ia import endpoint for Archive.org items, requiring an ocaid identifier rather than direct data upload.
    Request Format:

        NOTE: This function modifies the passed-in rec in place.
    """
    required_fields = [
        'title',
        'source_records',
    ]  # ['authors', 'publishers', 'publish_date']
    for field in required_fields:
        if not rec.get(field):
            raise RequiredField(field)

    # Ensure source_records is a list.
    if not isinstance(rec['source_records'], list):
        rec['source_records'] = [rec['source_records']]

    # Split subtitle if required and not already present
    if ':' in rec.get('title', '') and not rec.get('subtitle'):
        title, subtitle = split_subtitle(rec.get('title'))
        if subtitle:
            rec['title'] = title
            rec['subtitle'] = subtitle

    rec = normalize_record_bibids(rec)

    # deduplicate authors
    rec['authors'] = uniq(rec.get('authors', []), dicthash)


def validate_publication_year(publication_year: int, override: bool = False) -> None:
    """
    Validate the publication year and raise an error if:
        - the book is published prior to 1500 AND override = False; or
        - the book is published in a future year.
    """
    if publication_year_too_old(publication_year) and not override:
        raise PublicationYearTooOld(publication_year)
    elif published_in_future_year(publication_year):
        raise PublishedInFutureYear(publication_year)


def validate_record(rec: dict, override_validation: bool = False) -> None:
    """
    Check the record for various issues.
    Each check raises an error or returns None. The override skips publication
    year, independent publisher, and source ISBN checks.
    """
    required_fields = [
        'title',
        'source_records',
    ]  # ['authors', 'publishers', 'publish_date']
    for field in required_fields:
        if not rec.get(field):
            raise RequiredField(field)

    if not override_validation:
        if publication_year := get_publication_year(rec.get('publish_date')):
            validate_publication_year(publication_year)

        if is_independently_published(rec.get('publishers', [])):
            raise IndependentlyPublished

        if needs_isbn_and_lacks_one(rec):
            raise SourceNeedsISBN


def find_match(rec, edition_pool) -> str | None:
    """Use rec to try to find an existing edition key that matches."""
    match = find_quick_match(rec)
    if not match:
        match = find_exact_match(rec, edition_pool)

    if not match:
        # Add 'full_title' to the rec by conjoining 'title' and 'subtitle'.
        # expand_record() uses this for matching.
        rec['full_title'] = rec['title']
        if subtitle := rec.get('subtitle'):
            rec['full_title'] += ' ' + subtitle

    match = pattern.search(str(publish_date))

    return int(match.group(0)) if match else None


def published_in_future_year(publish_year: int) -> bool:
    """
    Look to see if a book is published in a future year as compared to the
    current year.

    Some import sources have publication dates in a future year, and the
    likelihood is high that this is bad data. So we don't want to import these.
    """
    return publish_year > datetime.datetime.now().year


def publication_year_too_old(publish_year: int) -> bool:
    """
    Returns True if publish_year is < 1,500 CE, and False otherwise.
    """
    return publish_year < 1500


def is_independently_published(publishers: list[str]) -> bool:
    """
    Return True if publishers contains (casefolded) "independently published".
    """
    return any(
        publisher.casefold() == "independently published" for publisher in publishers
    )


def is_promise_item(rec: dict) -> bool:
    """Return whether any source record starts with ``promise:``."""
    return any(
        source.casefold().startswith('promise:')
        for source in rec.get('source_records', [])
    )


def needs_isbn_and_lacks_one(rec: dict) -> bool:
    """
    Check a record to see if the source indicates that an ISBN is
    required.

    If an ISBN is NOT required, return False. If an ISBN is required:
        - return False if an ISBN is present (because the rec needs an ISBN and
          has one); or
        - return True if there's no ISBN.

    This exists because certain sources do not have great records and requiring
    an ISBN may help improve quality:
        https://docs.google.com/document/d/1dlN9klj27HeidWn3G9GUYwDNZ2F5ORoEZnG4L-7PcgA/edit#heading=h.1t78b24dg68q

    :param dict rec: an import dictionary record.
    """

    def needs_isbn(rec: dict) -> bool:
        sources_requiring_isbn = ['amazon', 'bwb']
        return any(
            record.split(":")[0] in sources_requiring_isbn
            for record in rec.get('source_records', [])
        )

    def has_isbn(rec: dict) -> bool:
        return any(rec.get('isbn_10', []) or rec.get('isbn_13', []))
